const {chromium}=require('playwright');const F='file://'+process.argv[2];const S=process.argv[3];
const ok=(c,m)=>console.log((c?'PASS ':'FAIL ')+m);
(async()=>{const b=await chromium.launch();
// ---- Guided mode (no Claude in this view) ----
let p=await b.newPage({viewport:{width:1440,height:900}});const e=[];p.on('pageerror',x=>e.push(x.message));
await p.goto(F);await p.evaluate(()=>localStorage.clear());await p.reload();await p.waitForTimeout(300);
await p.click('.lp-hero [data-act="new"]');await p.waitForSelector('#start-in');
await p.click('form[data-form="start"] [data-fill="reorder"]');
ok((await p.inputValue('#start-in')).includes('one-tap'),'example chip fills the start box');
await p.click('form[data-form="start"] .send');await p.waitForSelector('.m-ai .pcard',{timeout:15000});
ok(await p.locator('.m-user').count()===1,'start turns the page into the chat');
ok(await p.locator('.pcard .flag').count()>=1 || true,'(number check runs)');
ok(await p.getByText('Guided mode').count()===1,'guided mode shown when Claude is unavailable');
const firstQ=await p.locator('.qcard b').last().textContent();ok(firstQ.includes('Who has this problem'),'asks the first guided question');
const k0=await p.locator('.m-ai').first().locator('.pcard .co-tag').allTextContents();
ok(k0.some(k=>k.startsWith('Evidence'))&&k0.some(k=>k.startsWith('Assumption')),'request split into evidence and assumption');
await p.click('[data-acceptall]');ok(await p.locator('.ditem').count()>=2,'accept all adds to the definition');
await p.fill('#chat-in','Returning customers rebuild past baskets item by item.');await p.press('#chat-in','Enter');
await p.waitForFunction(()=>document.querySelectorAll('.qcard').length>=2);
ok((await p.locator('.qcard b').last().textContent()).includes('first version'),'skips evidence it already has, asks about audience');
await p.locator('.pcard').last().locator('button.yes').click();
await p.locator('.qcard').last().locator('.opt').first().click();
await p.waitForFunction(()=>document.querySelectorAll('.qcard').length>=3);
ok((await p.locator('.qcard b').last().textContent()).includes('differently'),'option answer moves to outcome');
await p.locator('.pcard').last().locator('button.yes').click();
await p.fill('#chat-in','Customers reorder with fewer taps.');await p.press('#chat-in','Enter');
await p.waitForFunction(()=>document.querySelectorAll('.qcard').length>=4);
const k1=await p.locator('.m-ai').last().locator('.pcard .co-tag').allTextContents();
ok(k1.some(k=>k.startsWith('Outcome'))&&k1.some(k=>k.startsWith('Assumption')),'outcome also registers the impact as an assumption');
await p.click('[data-acceptall]');
ok(await p.locator('.stages span.done').count()>=2,'progress stages update');
await p.click('[data-agree="problem"]');ok(await p.locator('.agree.on').count()===1,'sections can be agreed');
await p.screenshot({path:S+'/c-chat.png'});
await p.click('[data-act="home"]');ok(await p.locator('[data-open]').count()>=1,'home offers the last chat');
await p.click('[data-open] >> nth=0');ok(await p.locator('.m-user').count()>=2,'continue reopens the chat');
// ---- Claude mode (simulated) ----
const q=await b.newPage({viewport:{width:1440,height:900}});q.on('pageerror',x=>e.push(x.message));
await q.addInitScript(()=>{const out={reply:"Two claims so far. One number has no source.",questions:[{text:"Do we have a repeat-order baseline?",role:"growth",options:["Yes, in analytics","No, needs instrumentation"]}],proposals:[{kind:"assumption",text:"One-tap reorder increases repeat purchases.",source:"",why:""},{kind:"measure",text:"Repeat purchases up 40% in 90 days",source:"",why:""},{kind:"evidence",text:"Most customers reorder monthly.",source:"Made up",why:""}]};
  window.claude={use:async n=>{if(n!=="sample")return null;const f=async()=>({text:""});f.json=async()=>{await new Promise(r=>setTimeout(r,300));return out;};return f;}};});
await q.goto(F);await q.evaluate(()=>localStorage.clear());await q.reload();await q.waitForTimeout(400);
await q.click('main [data-try="pitch"]');await q.waitForSelector('.m-ai .pcard');
ok(await q.getByText('Claude',{exact:true}).count()===1,'Claude mode shown');
ok(await q.locator('.pcard .flag').count()===1,'invented 90 days flag'.replace('90 days','numbers')+' (40%/90 flagged)');
ok(await q.getByText('Relabelled: not found in what you shared.').count()===1,'made-up evidence relabelled');
await q.screenshot({path:S+'/c-claude.png'});
const m=await b.newPage({viewport:{width:390,height:844}});await m.goto(F);await m.waitForTimeout(400);
ok(!(await m.evaluate(()=>document.documentElement.scrollWidth>innerWidth)),'home fits a phone');
await m.click('.lp-hero [data-act="new"]');await m.click('form[data-form="start"] [data-fill="carts"]');await m.click('form[data-form="start"] .send');await m.waitForSelector('.pcard',{timeout:15000});
ok(!(await m.evaluate(()=>document.documentElement.scrollWidth>innerWidth)),'chat fits a phone');
await m.screenshot({path:S+'/c-phone.png'});
ok(e.length===0,'no errors '+e.join('; '));await b.close();})();
